  const f=await fixture();f.reader.add('b','last');f.host.querySelector('textarea')!.value='New thought\n\n- Body list';await f.reader.flush();const doc=await f.service.read(f.path),added=thoughts(doc.sections[0]!).find(n=>n.text.startsWith('New thought'))!;expect(added.parent).toBe('b');f.reader.retire();f.reader.render(f.path,doc,doc.sections[0]!);expect(f.reader.list.textContent).toBeTruthy();f.done();
