 it('unloads Markdown render children and navigation listeners when the chapter is retired',async()=>{
  const renderer=vi.mocked(MarkdownRenderer),original=renderer.render.getMockImplementation()!,alive=new Set<Component>();renderer.render.mockImplementation(async(_app,text,host,_path,lifecycle)=>{host.setText(text);const child=lifecycle.addChild(new Component());alive.add(child);child.register(()=>alive.delete(child));});let f:Awaited<ReturnType<typeof fixture>>|undefined;
  try{f=await fixture();f.reader.navigate('b');expect(alive.size).toBe(3);const cleanup=vi.fn();(f.reader as unknown as {lifecycle:Component}).lifecycle.register(cleanup);f.reader.retire();expect(alive.size).toBe(0);expect(cleanup).toHaveBeenCalledOnce();expect(f.reader.list.childElementCount).toBe(0);}finally{f?.done();renderer.render.mockImplementation(original);}
 });
